import { SUPER_G_NAME, ANIMATIONS } from '../../constants/Constants';
export default class Animation {
  execute(cellConfig, caseObj, result) {
    if (result === true) {
      this.start(cellConfig, caseObj);
    } else {
      this.stop(cellConfig, caseObj);
    }
  }
  start(cellConfig, caseObj) {
    let animationObj = caseObj.touchOff?.animation;
    let selector = animationObj?.selector ?? [];
    if (!selector.length) {
      selector.push(SUPER_G_NAME);
    }
    const effect = caseObj.touchOff?.animation?.effect;
    const classs = [];
    const styles = [];
    if (effect) {
      for (let item of effect) {
        let findAnim = ANIMATIONS.find((anim) => anim.key === item.key);
        if (findAnim && typeof findAnim.handle === 'function') {
          findAnim.handle(cellConfig.cell);
        }

        if (item.class) {
          classs.push(item.class);
        }
        if (item.style) {
          styles.push(item);
        }
      }
    }
    if (classs.length) {
      if (classs.length) {
        let classStr = classs.join(' ');
        let oldClasss = cellConfig.cell.attr(`${selector}/class`);
        if (oldClasss) {
          classStr += ' ' + oldClasss;
        }
        selector.forEach((forSelector) => {
          cellConfig.cell.attr(`${forSelector}/class`, classStr);
        });
      }
    }
    if (styles.length) {
      if (styles.length) {
        let styleStr = '';
        for (let item of Object.values(styles)) {
          for (let [key, value] of Object.entries(item.style)) {
            styleStr += `${key}:${value};`;
          }
        }
        selector.forEach((forSelector) => {
          cellConfig.cell.attr(`${forSelector}/style`, '');
          cellConfig.cell.attr(`${forSelector}/style`, styleStr);
        });
      }
    }
  }
  stop(cellConfig, caseObj) {
    const effect = caseObj.touchOff?.animation?.effect;
    const classs = [];
    const styles = [];
    if (effect) {
      for (let item of effect) {
        let findAnim = ANIMATIONS.find((anim) => anim.key === item.key);
        if (findAnim && typeof findAnim.orgHandle === 'function') {
          findAnim.orgHandle(cellConfig.cell, cellConfig.orgCell);
        }
        if (item.class) {
          classs.push(item.class);
        }
        if (item.style) {
          styles.push(item);
        }
      }
    }
    if (classs.length) {
      let animationObj = caseObj.touchOff?.animation;
      let selector = animationObj.selector ?? [];
      if (!selector.length) {
        selector.push(SUPER_G_NAME);
      }
      if (classs.length) {
        selector.forEach((forSelector) => {
          let nodeClasss = cellConfig.cell.attr(`${forSelector}/class`);
          if (nodeClasss) {
            classs.forEach((clazz) => {
              nodeClasss = nodeClasss.replaceAll(clazz, '');
            });

            cellConfig.cell.attr(`${forSelector}/class`, nodeClasss);
          }
        });
      }
      if (styles.length) {
        selector.forEach((forSelector) => {
          /*let nodeStyle = cellConfig.cell.attr(`${forSelector}/style`);
          for (let item of Object.values(styles)) {
            for (let [key, value] of Object.entries(item.style)) {
              nodeStyle.replaceAll(`${key}:${value}`, '');
              console.log(`${key}:${value}`, nodeStyle);
            }
          }
          cellConfig.cell.attr(`${forSelector}/style`, nodeStyle);*/
          // cellConfig.cell.attr(cellConfig.orgCell.attrs);
          cellConfig.cell.attr(`${forSelector}/style`, '');
        });
      }
    }
  }
}
