import SuperNode from './SuperNode';
import { Timing } from '@antv/x6';
import graphStore from '../store/GraphStore';
import { D3_G_NAME, SUPER_G_NAME } from '../constants/Constants';
class GroupNode extends SuperNode {
  constructor(metadata = {}) {
    super(metadata);
    this.xdChildren = [];
    /*处理组编辑状态中途如果刷新浏览器，则重新加载时无法恢复组合*/
    let isLock = this.propGroupLock();
    if (isLock) {
      // 延迟执行，因为对象初始化时获取不到children
      setTimeout(() => {
        this.propGroupLock(false);
        this.children.forEach((node) => {
          node.propGroupLock(true);
        });
      }, 200);
    }

    this.on('change:angle', ({ cell, current, previous, options }) => {
      console.log(current, previous);
      const others = options.others;

      let center = this.getBBox().getCenter();
      if (others?.parentCenter) {
        center = others.parentCenter;
      }
      cell.children?.forEach((children) => {
        if (children.isNode()) {
          children.rotate?.(current, {
            center: center,
            absolute: true,
            others: { parentCenter: center }
          });
        } else {
          const { x: cx, y: cy } = center;
          const sourceNode = children.getSourceNode();
          if (!sourceNode) {
            let { x, y } = children.getSource();
            let newPoint = this.rotatePoint(x, y, cx, cy, current - previous);
            children.setSource(newPoint);
          }
          const targetNode = children.getTargetNode();
          if (!targetNode) {
            let { x, y } = children.getTarget();
            let newPoint = this.rotatePoint(x, y, cx, cy, current - previous);
            children.setTarget(newPoint);
          }
          let vertices = children.getVertices();
          let rvertices = [];
          vertices.forEach(({ x, y }) => {
            rvertices.push(this.rotatePoint(x, y, cx, cy, current - previous));
          });
          children.setVertices(rvertices);

          const view = graphStore.getGraph().findViewByCell(children);
          const routePoints = view.routePoints;
          let routeVertices = [];
          routePoints.forEach(({ x, y }) => {
            routeVertices.push(
              this.rotatePoint(x, y, cx, cy, current - previous)
            );
          });
          view.routePoints = routeVertices;
        }
      });
    });
    this.on('change:size', ({ cell, current, options }) => {
      const { width, height } = cell.size();
      const { x: px, y: py } = cell.position();
      if (!Object.keys(this.xdChildren).length) {
        cell.calcChildren(cell.children, false);
      }
      cell.children?.forEach((children) => {
        let xd = this.xdChildren[children.id];
        if (xd) {
          if (children.isNode()) {
            children.resize(width * xd.cw, height * xd.ch);
            children.position(width * xd.cx, height * xd.cy, {
              relative: true
            });
          } else {
            if (xd.source) {
              let x = width * xd.source.cx + px;
              let y = height * xd.source.cy + py;
              children.setSource({ x, y });
            }
            if (xd.target) {
              let x = width * xd.target.cx + px;
              let y = height * xd.target.cy + py;
              children.setTarget({ x, y });
            }
            if (xd.vertices?.length) {
              let vertices = children.getVertices();
              let rvertices = [];
              vertices.forEach((vertice, index) => {
                let { cx, cy } = xd.vertices[index];
                let x = width * cx + px;
                let y = height * cy + py;
                rvertices.push({ x, y });
              });
              children.setVertices(rvertices);
            }
          }
        }
      });
    });
  }

  rotatePoint(x, y, cx, cy, angle) {
    // 将角度从度转换为弧度
    const angleInRadians = angle * (Math.PI / 180);

    // 计算旋转矩阵中的值
    const cosTheta = Math.cos(angleInRadians);
    const sinTheta = Math.sin(angleInRadians);

    // 原始点相对于旋转中心的坐标
    const tx = x - cx;
    const ty = y - cy;

    // 旋转后的相对坐标
    const rotatedX = tx * cosTheta - ty * sinTheta;
    const rotatedY = tx * sinTheta + ty * cosTheta;

    // 新的绝对坐标
    const newX = rotatedX + cx;
    const newY = rotatedY + cy;

    return { x: newX, y: newY };
  }
  calcMinMax(mmObj, { x, y, mWidth, mHeight }) {
    if (mmObj.minX === null) {
      if (x !== undefined) {
        mmObj.minX = x;
        mmObj.minY = y;
      }
      if (mWidth !== undefined) {
        mmObj.maxX = mWidth;
        mmObj.maxY = mHeight;
      }
    } else {
      if (x !== undefined) {
        mmObj.minX = Math.min(mmObj.minX, x);
        mmObj.minY = Math.min(mmObj.minY, y);
      }
      if (mWidth !== undefined) {
        mmObj.maxX = Math.max(mmObj.maxX, mWidth);
        mmObj.maxY = Math.max(mmObj.maxY, mHeight);
      }
    }
  }
  calcXD({ x, y, minX, minY, gWidth, gHeight }) {
    let cx = (x - minX) / gWidth; //相对位置X
    let cy = (y - minY) / gHeight; //相对位置Y
    return {
      cx,
      cy
    };
  }
  calcChildren(selectCells, silent = true) {
    if (!selectCells) {
      selectCells = this.children;
    }
    let mmObj = {
      minX: null,
      minY: null,
      maxX: null,
      maxY: null
    };
    selectCells.forEach((fCell) => {
      if (fCell.isNode()) {
        let { x, y } = fCell.position();
        let { width, height } = fCell.size();
        let mWidth = x + width;
        let mHeight = y + height;
        this.calcMinMax(mmObj, { x, y, mWidth, mHeight });
      } else {
        const sourceNode = fCell.getSourceNode();
        let points = [];
        if (!sourceNode) {
          points.push(fCell.getSource());
        }
        const targetNode = fCell.getTargetNode();
        if (!targetNode) {
          points.push(fCell.getTarget());
        }
        let vertices = fCell.getVertices();
        points.push(...vertices);

        const view = graphStore.getGraph().findViewByCell(fCell);
        const routePoints = view.routePoints;
        points.push(...routePoints);

        points.forEach(({ x, y }) => {
          this.calcMinMax(mmObj, { x, y });
          this.calcMinMax(mmObj, { mWidth: x, mHeight: y });
        });
      }
    });
    let { maxX, maxY, minX, minY } = mmObj;
    let gWidth = maxX - minX;
    let gHeight = maxY - minY;

    selectCells.forEach((fCell) => {
      if (fCell.isNode()) {
        let { x, y } = fCell.position();
        let { cx, cy } = this.calcXD({ x, y, minX, minY, gWidth, gHeight });

        let { width, height } = fCell.size();
        let cw = width / gWidth; //相对宽度
        let ch = height / gHeight; //相对高度
        let xd = {
          cx,
          cy,
          cw,
          ch
        };
        this.xdChildren[fCell.id] = xd;
      } else {
        let xd = {};
        const sourceNode = fCell.getSourceNode();
        if (!sourceNode) {
          const { x, y } = fCell.getSource();
          xd.source = this.calcXD({ x, y, minX, minY, gWidth, gHeight });
        }
        const targetNode = fCell.getTargetNode();
        if (!targetNode) {
          const { x, y } = fCell.getTarget();
          xd.target = this.calcXD({ x, y, minX, minY, gWidth, gHeight });
        }
        let vertices = fCell.getVertices();
        xd.vertices = [];
        vertices.forEach(({ x, y }) => {
          let xy = this.calcXD({ x, y, minX, minY, gWidth, gHeight });
          xd.vertices.push(xy);
        });

        const view = graphStore.getGraph().findViewByCell(fCell);
        const routePoints = view.routePoints;
        xd.routeVertices = [];
        routePoints.forEach(({ x, y }) => {
          let xy = this.calcXD({ x, y, minX, minY, gWidth, gHeight });
          xd.routeVertices.push(xy);
        });
        this.xdChildren[fCell.id] = xd;
      }
    });
    // this.prop('xdChildren', this.xdChildren);
    if (silent) {
      this.position(minX, minY);
      this.resize(gWidth, gHeight);
    }
  }
  calcEdge(fCell) {
    let sNode = fCell.getSourceNode();
    let tNode = fCell.getTargetNode();
    let result = [];
    if (!sNode) {
      let source = fCell.getSource();
      let sourceNode = this.createEdgePointNode(source);
      fCell.setSource(sourceNode);
      result.push(sourceNode);
    }
    if (!tNode) {
      let target = fCell.getTarget();
      let targetNode = this.createEdgePointNode(target);
      fCell.setTarget(targetNode);
      result.push(targetNode);
    }
    return result;
    /*let vertices = fCell.getVertices();
    let xd = [];
    vertices.forEach((v) => {
      xd.push({
        cx: (v.x - minX) / gWidth,
        cy: (v.y - minY) / gHeight
      });
    });*/
  }
  createEdgePointNode({ x, y }) {
    return graphStore.getGraph().addNode({
      shape: 'edge-point-node',
      x,
      y,
      visible: false,
      width: 1,
      height: 1,
      'group-lock': true
      // lock: true
    });
  }

  childrenTransition({ x, y, delay, duration, timing, finish, orgX, orgY }) {
    if (!this.children?.length) {
      return;
    }
    if (!Object.keys(this.xdChildren).length) {
      this.calcChildren(this.children, false);
    }
    const { width, height } = this.size();
    this.children.forEach((children) => {
      let xd = this.xdChildren[children.id];

      children.transition(
        'position',
        { x: x + width * xd.cx, y: y + height * xd.cy },
        {
          delay: delay, //延时执行
          duration: duration,
          timing: Timing.decorators.reverse(Timing[timing]),
          finish: () => {
            finish(children, orgX + width * xd.cx, orgY + height * xd.cy);
          }
        }
      );
    });
  }
  hide() {
    graphStore.getGraph().startBatch('group-hide');
    super.hide();
    this.children?.forEach?.((cell) => {
      cell.hide();
    });
    graphStore.getGraph().stopBatch('group-hide');
  }
  show() {
    graphStore.getGraph().startBatch('group-show');
    super.show();
    this.children?.forEach?.((cell) => {
      cell.show();
    });
    graphStore.getGraph().stopBatch('group-show');
  }
}
GroupNode.config({
  inherit: 'rect',
  markup: [
    {
      tagName: 'g',
      selector: D3_G_NAME,
      children: [
        {
          tagName: 'g',
          selector: SUPER_G_NAME,
          children: [
            {
              tagName: 'rect',
              selector: 'body'
            }
          ]
        }
      ]
    }
  ],
  attrs: {
    body: {
      refWidth: 1,
      refHeight: 1,
      stroke: 'none',
      strokeWidth: 0,
      fill: 'none'
    },
    [D3_G_NAME]: {
      pointerEvents: 'visibleFill'
      /*style: {
        pointerEvents: 'none'
      }*/
    }
  }
});
