import {
  clearMultiSelectionChrome,
  selectCellOnPointer
} from '../util/CellSelectionUtil';
import { INIT_NODE_IDS } from '../constants/Constants';

/** 同一点判定容差（图坐标 px） */
const HIT_TOLERANCE = 6;
const MIN_STACK_SIZE = 2;
/** 两次点击视为「一轮轮换」的最大间隔（ms） */
const CLICK_PAIR_GAP_MS = 800;
/** 临时隐藏遮挡层（仅挂在 CellView DOM，不进 JSON / History） */
const PENETRATE_HIDE_CLASS = 'stack-select-penetrate-hide';

let disposeFn = null;
/** @type {string[]} 当前被临时隐藏的遮挡图元 id */
let hiddenCellIds = [];
/** 穿透选中的目标 id，用于选中变化时决定是否还原 */
let penetrateTargetId = null;
/** 轮换切选中，避免 selection:changed 提前还原隐藏 */
let isCycling = false;

function defaultIsSelectable(cell) {
  if (INIT_NODE_IDS.includes(cell.id)) {
    return false;
  }
  const lock = cell.prop('lock');
  const groupLock = cell.prop('group-lock');
  return !lock && !groupLock;
}

function getStackAtPoint(graph, point, isSelectable) {
  const views = graph.findViewsFromPoint(point);
  const seen = new Set();
  const cells = [];
  views.forEach((view) => {
    const cell = view?.cell;
    if (!cell || seen.has(cell.id) || !isSelectable(cell)) {
      return;
    }
    seen.add(cell.id);
    cells.push(cell);
  });
  cells.sort((a, b) => b.getZIndex() - a.getZIndex());
  return cells;
}

function isSamePoint(a, b) {
  return (
    Math.abs(a.x - b.x) <= HIT_TOLERANCE &&
    Math.abs(a.y - b.y) <= HIT_TOLERANCE
  );
}

function isGroupEditNode(node) {
  if (!node?.isNode?.()) {
    return false;
  }
  const children = node.children;
  if (!children?.length) {
    return false;
  }
  const isGroupLock = node.propGroupLock?.() ?? true;
  return !isGroupLock;
}

function shouldSkipStackCycle(stack) {
  const top = stack[0];
  return isGroupEditNode(top);
}

function getCellView(graph, cell) {
  if (!graph || !cell) {
    return null;
  }
  return graph.findViewByCell?.(cell) || graph.findView?.(cell) || null;
}

/** 还原本次穿透隐藏的遮挡层 */
export function clearStackSelectPenetrateHide(graph) {
  if (!hiddenCellIds.length) {
    penetrateTargetId = null;
    return;
  }
  hiddenCellIds.forEach((id) => {
    const cell = graph?.getCellById?.(id);
    const view = getCellView(graph, cell);
    view?.removeClass?.(PENETRATE_HIDE_CLASS);
  });
  hiddenCellIds = [];
  penetrateTargetId = null;
}

/**
 * 隐藏选中目标上方的遮挡层（stack 按 z 从高到低）
 */
function hideCellsAbove(graph, cycleStack, selectedIndex) {
  clearStackSelectPenetrateHide(graph);
  if (selectedIndex <= 0) {
    return;
  }
  for (let i = 0; i < selectedIndex; i += 1) {
    const cell = cycleStack[i];
    if (!cell) {
      continue;
    }
    const view = getCellView(graph, cell);
    if (!view?.addClass) {
      continue;
    }
    view.addClass(PENETRATE_HIDE_CLASS);
    hiddenCellIds.push(cell.id);
  }
}

function syncHideAfterSelect(graph, cycleStack, selected) {
  const idx = cycleStack.findIndex((c) => c.id === selected.id);
  penetrateTargetId = selected.id;
  if (idx <= 0) {
    clearStackSelectPenetrateHide(graph);
    penetrateTargetId = selected.id;
    return;
  }
  hideCellsAbove(graph, cycleStack, idx);
  penetrateTargetId = selected.id;
}

function selectCell(graph, cell, e = {}) {
  selectCellOnPointer(graph, cell, e);
}

function stopPointerBubble(e) {
  e?.stopPropagation?.();
  e?.preventDefault?.();
}

function isAltPointerEvent(e) {
  return !!e?.altKey;
}

/** Alt 叠放穿透：新点从顶层/首个未选中层开始；同点再点轮换到下一层 */
function resolveAltCycleIndex(cycleStack, graph, samePointAsLast, currentIndex) {
  const n = cycleStack.length;
  if (!samePointAsLast) {
    const firstUnselected = cycleStack.findIndex((c) => !graph.isSelected(c));
    return firstUnselected >= 0 ? firstUnselected : 0;
  }
  let next = (currentIndex + 1) % n;
  let tries = 0;
  while (tries < n && graph.isSelected(cycleStack[next])) {
    next = (next + 1) % n;
    tries += 1;
  }
  return next;
}

/** Transform 插件会在 cell:click 之后按 DOM 命中再建变形框，须延后对齐到真实选中节点 */
function syncTransformWidgetAfterCycle(graph, cell) {
  queueMicrotask(() => {
    const selected = graph.getSelectedCells();
    if (selected.length !== 1 || selected[0].id !== cell.id) {
      return;
    }
    if (!cell.isNode?.() || cell.isEdge?.()) {
      return;
    }
    graph.clearTransformWidgets();
    graph.createTransformWidget(cell);
  });
}

/** 轮换选中后对齐变形框；若仍为多选则清掉编辑控件 */
function syncSelectionVisualsAfterCycle(graph, cell) {
  queueMicrotask(() => {
    const selected = graph.getSelectedCells();
    if (selected.length > 1) {
      clearMultiSelectionChrome(graph);
      return;
    }
    syncTransformWidgetAfterCycle(graph, cell);
  });
}

/**
 * 同位置两次点击（间隔内）或 Alt+点击轮换叠放选中；
 * 上方遮挡层用临时 class 隐藏，不改 zIndex。
 * 组合顶层仍走 node:dblclick 进组编辑，不在此处理。
 */
export function initStackSelectCycle(graph, options = {}) {
  disposeStackSelectCycle();

  const isSelectable = options.isSelectable || defaultIsSelectable;
  const isEnabled = options.isEnabled || (() => true);

  let lastPoint = null;
  let lastStackIds = null;
  let cycleIndex = 0;

  /** 同点连点：等待第二次点击 */
  let pendingClickPoint = null;
  let pendingClickTime = 0;
  let pendingClickTimer = null;

  const clearPendingClick = () => {
    if (pendingClickTimer != null) {
      clearTimeout(pendingClickTimer);
      pendingClickTimer = null;
    }
    pendingClickPoint = null;
    pendingClickTime = 0;
  };

  const resetCycle = () => {
    lastPoint = null;
    lastStackIds = null;
    cycleIndex = 0;
    clearPendingClick();
  };

  const getCycleStack = (stackIds) => {
    return stackIds
      .map((id) => graph.getCellById(id))
      .filter((cell) => cell && isSelectable(cell));
  };

  /** 上层已隐藏时 findViewsFromPoint 会丢层，同点续点用缓存栈 */
  const isStackCyclePoint = (point) => {
    if (
      lastPoint != null &&
      isSamePoint(lastPoint, point) &&
      lastStackIds?.length >= MIN_STACK_SIZE &&
      hiddenCellIds.length > 0
    ) {
      const cached = getCycleStack(lastStackIds);
      return cached.length >= MIN_STACK_SIZE && !shouldSkipStackCycle(cached);
    }
    const stack = getStackAtPoint(graph, point, isSelectable);
    return stack.length >= MIN_STACK_SIZE && !shouldSkipStackCycle(stack);
  };

  const advanceCycle = (
    cycleStack,
    pointerEvent = {},
    samePointAsLast = false
  ) => {
    if (isAltPointerEvent(pointerEvent)) {
      cycleIndex = resolveAltCycleIndex(
        cycleStack,
        graph,
        samePointAsLast,
        cycleIndex
      );
    } else {
      cycleIndex = (cycleIndex + 1) % cycleStack.length;
    }
    const selected = cycleStack[cycleIndex];
    isCycling = true;
    try {
      // Alt 穿透只切选中，不走 Ctrl/Shift 多选追加
      selectCell(
        graph,
        selected,
        isAltPointerEvent(pointerEvent) ? {} : pointerEvent
      );
      syncHideAfterSelect(graph, cycleStack, selected);
      syncSelectionVisualsAfterCycle(graph, selected);
    } finally {
      queueMicrotask(() => {
        isCycling = false;
      });
    }
  };

  const runCycleStep = (point, pointerEvent = {}) => {
    const samePointAsLast =
      lastPoint != null && isSamePoint(lastPoint, point);

    if (samePointAsLast && lastStackIds?.length >= MIN_STACK_SIZE) {
      const cycleStack = getCycleStack(lastStackIds);
      if (cycleStack.length < MIN_STACK_SIZE) {
        clearStackSelectPenetrateHide(graph);
        resetCycle();
        return;
      }
      advanceCycle(cycleStack, pointerEvent, true);
      lastPoint = { x: point.x, y: point.y };
      return;
    }

    // 换点穿透：先还原旧隐藏，再按真实命中取栈
    clearStackSelectPenetrateHide(graph);

    const stack = getStackAtPoint(graph, point, isSelectable);
    if (stack.length < MIN_STACK_SIZE) {
      resetCycle();
      return;
    }
    if (shouldSkipStackCycle(stack)) {
      resetCycle();
      return;
    }

    lastStackIds = stack.map((c) => c.id);
    lastPoint = { x: point.x, y: point.y };
    cycleIndex = -1;

    const cycleStack = getCycleStack(lastStackIds);
    if (cycleStack.length < MIN_STACK_SIZE) {
      resetCycle();
      return;
    }

    advanceCycle(cycleStack, pointerEvent, false);
  };

  const onCellMouseDown = ({ e, x, y }) => {
    if (!isEnabled()) {
      return;
    }
    const isAltCycle = e.altKey;
    if (!isAltCycle || e.shiftKey || e.ctrlKey || e.metaKey) {
      return;
    }
    if (isStackCyclePoint({ x, y })) {
      stopPointerBubble(e);
    }
  };

  const onCellClick = ({ e, x, y }) => {
    if (!isEnabled()) {
      clearStackSelectPenetrateHide(graph);
      resetCycle();
      return;
    }

    const point = { x, y };
    const isAltCycle = e.altKey;
    const hasOtherModifier = e.shiftKey || e.ctrlKey || e.metaKey;
    if (hasOtherModifier) {
      resetCycle();
      return;
    }

    // Alt+点击叠放：轮换选中下层并临时隐藏上方遮挡；非叠放不拦截
    if (isAltCycle) {
      if (isStackCyclePoint(point)) {
        stopPointerBubble(e);
        runCycleStep(point, e);
      } else {
        clearStackSelectPenetrateHide(graph);
        resetCycle();
      }
      return;
    }

    const now = Date.now();
    const isSecondClick =
      pendingClickPoint != null &&
      isSamePoint(pendingClickPoint, point) &&
      now - pendingClickTime <= CLICK_PAIR_GAP_MS;

    if (isSecondClick) {
      clearPendingClick();
      runCycleStep(point);
      return;
    }

    clearPendingClick();
    pendingClickPoint = { x: point.x, y: point.y };
    pendingClickTime = now;
    pendingClickTimer = setTimeout(clearPendingClick, CLICK_PAIR_GAP_MS);
  };

  const onBlankClick = () => {
    clearStackSelectPenetrateHide(graph);
    resetCycle();
  };

  const onBlankMouseDown = () => {
    clearStackSelectPenetrateHide(graph);
  };

  const onSelectionChanged = () => {
    if (isCycling || !hiddenCellIds.length || !penetrateTargetId) {
      return;
    }
    const selected = graph.getSelectedCells();
    const stillSelected = selected.some((c) => c.id === penetrateTargetId);
    if (!stillSelected) {
      clearStackSelectPenetrateHide(graph);
    }
  };

  graph.on('cell:mousedown', onCellMouseDown);
  graph.on('cell:click', onCellClick);
  graph.on('blank:click', onBlankClick);
  graph.on('blank:mousedown', onBlankMouseDown);
  graph.on('selection:changed', onSelectionChanged);

  disposeFn = () => {
    graph.off('cell:mousedown', onCellMouseDown);
    graph.off('cell:click', onCellClick);
    graph.off('blank:click', onBlankClick);
    graph.off('blank:mousedown', onBlankMouseDown);
    graph.off('selection:changed', onSelectionChanged);
    clearStackSelectPenetrateHide(graph);
    resetCycle();
    isCycling = false;
    disposeFn = null;
  };

  return disposeFn;
}

export function disposeStackSelectCycle() {
  if (disposeFn) {
    disposeFn();
  }
}
