import { changeSelectCells } from './Utils';

/** 端点未挂在节点上的自由边（横线/竖线/手绘线条等） */
export function isFreeEdge(cell) {
  if (!cell?.isEdge?.()) {
    return false;
  }
  return !cell.getSourceCellId?.() && !cell.getTargetCellId?.();
}

export function partitionAlignCells(cells) {
  const nodes = [];
  const edges = [];
  (cells || []).forEach((cell) => {
    if (cell.isEdge?.()) {
      if (isFreeEdge(cell)) {
        edges.push(cell);
      }
    } else {
      nodes.push(cell);
    }
  });
  return { nodes, edges };
}

/** 对齐/等距工具栏：节点 ≥2 或 自由边 ≥2 */
export function canUseAlignTools(cells) {
  const { nodes, edges } = partitionAlignCells(cells);
  return nodes.length >= 2 || edges.length >= 2;
}

/** 平均分布需 ≥3 个同类图元 */
export function canUseDistributeTools(cells) {
  const { nodes, edges } = partitionAlignCells(cells);
  return nodes.length >= 3 || edges.length >= 3;
}

export function countAlignableForToolbar(cells) {
  const { nodes, edges } = partitionAlignCells(cells);
  if (nodes.length >= 2) {
    return nodes.length;
  }
  if (edges.length >= 2) {
    return edges.length;
  }
  return Math.max(nodes.length, edges.length);
}

export function countDistributeForToolbar(cells) {
  const { nodes, edges } = partitionAlignCells(cells);
  if (nodes.length >= 3) {
    return nodes.length;
  }
  if (edges.length >= 3) {
    return edges.length;
  }
  return Math.max(nodes.length, edges.length);
}

export function hasPageAlignTarget(cells) {
  const { nodes, edges } = partitionAlignCells(cells);
  return nodes.length > 0 || edges.length > 0;
}

function isMultiSelectModifier(e) {
  return !!(e?.ctrlKey || e?.metaKey || e?.shiftKey);
}

const NODE_ADD_TOOLS = [
  'top-add-button',
  'right-add-button',
  'left-add-button',
  'bottom-add-button'
];

const EDGE_EDIT_TOOLS = [
  'vertices',
  'segments',
  'source-arrowhead',
  'target-arrowhead',
  'edge-editor'
];

/** 去掉单选时的节点四向按钮或边编辑工具 */
export function clearCellEditChrome(cell) {
  if (!cell) {
    return;
  }
  const tools = cell.isEdge?.() ? EDGE_EDIT_TOOLS : NODE_ADD_TOOLS;
  cell.removeTools?.(tools);
}

/** 多选时清除变形框，并去掉所有已选图元的编辑控件 */
export function clearMultiSelectionChrome(graph) {
  if (!graph) {
    return;
  }
  graph.clearTransformWidgets?.();
  graph.getSelectedCells().forEach(clearCellEditChrome);
}

/**
 * 单击选中图元；Ctrl/Shift 追加/切换（边与节点统一）
 */
export function selectCellOnPointer(graph, cell, e) {
  if (!cell || !graph) {
    return;
  }
  const multi = isMultiSelectModifier(e);
  if (multi) {
    if (graph.isSelected(cell)) {
      // graph.unselect(cell);
    } else {
      graph.select(cell, { append: true });
      if (graph.getSelectedCells().length > 1) {
        clearMultiSelectionChrome(graph);
      }
    }
    return;
  }
  if (cell.isEdge?.()) {
    graph.cleanSelection();
    graph.clearTransformWidgets();
    graph.select(cell);
    return;
  }
  changeSelectCells(graph, [cell]);
}
