import {
  SUPER_G_NAME,
  D3_G_NAME,
  IMG_SELECT_RECT,
  NODE_NEME
} from '../constants/Constants';
//递归获取树形结构中的所有markup
export const recursionMarkup = (markups, attrs) => {
  let resultMarkups = [];
  markups.forEach((markup) => {
    if (
      markup.selector !== SUPER_G_NAME &&
      markup.selector !== D3_G_NAME &&
      markup.selector !== IMG_SELECT_RECT
    ) {
      if (markup.selector != undefined && attrs[markup.selector] != undefined) {
        resultMarkups.push(markup);
      }
    }
    if (markup.children) {
      resultMarkups.push(...recursionMarkup(markup.children, attrs));
    }
  });

  return resultMarkups;
};
export const importAll = (r) => {
  let __modules = {};
  r.keys().forEach((key) => {
    let m = r(key).default;
    let n = m.name;
    __modules[n] = m;
  });
  return __modules;
};
export const insertImag = (graph, url, x, y) => {
  const img = new Image();
  // 设置 Image 对象的 src 为Base64数据
  img.src = url;
  // 当图像加载完成后触发该事件
  img.onload = () => {
    let width = img.width; // 获取图像宽度
    let height = img.height; // 获取图像高度

    let bl = height / width;
    width = 300;
    height = width * bl;
    x = x - width / 2;
    y = y - height / 2;
    let node = graph.createNode({
      shape: 'super-node',
      x,
      y,
      width,
      height,
      preserveAspectRatio: true,
      [NODE_NEME]: '图片_' + graph.getCellCount(),
      markup: [
        {
          tagName: 'g',
          selector: D3_G_NAME,
          children: [
            {
              tagName: 'g',
              selector: SUPER_G_NAME,
              children: [
                {
                  name: '图片',
                  tagName: 'image',
                  selector: 'body',
                  attrs: {
                    width,
                    height
                  }
                }
              ]
            }
          ]
        }
      ],
      attrs: {
        body: {
          refWidth: 1,
          refHeight: 1,
          href: url
        }
      }
    });
    graph.addNode(node);
    changeSelectCells(graph, [node]);
  };
};
/* 切换选中节点 */
export const changeSelectCells = (graph, cells) => {
  if (!cells?.length) {
    return;
  }
  graph.cleanSelection();
  graph.clearTransformWidgets();
  if (cells.length === 1 && !cells[0].isEdge()) {
    graph.createTransformWidget(cells[0]);
  }
  graph.select(cells);
  cells.forEach((cell) => {
    if (cell.isEdge?.()) {
      cell.removeTools?.(['vertices', 'segments']);
    }
  });
};
export function digit(value, length = 2) {
  if (value == null) {
    return '';
  }
  if (String(value).length >= length) {
    return String(value);
  }
  return (Array(length).join('0') + value).slice(-length);
}
export function toDateString(time, format = 'yyyy-MM-dd HH:mm:ss') {
  if (!time) {
    return '';
  }
  const transformStr = (str) => {
    if (typeof str === 'string') {
      if (str.includes('T')) {
        return str.replace(/\//g, '-');
      } else {
        return str.replace(/-/g, '/');
      }
    } else if (typeof str === 'number' && String(str).length === 10) {
      return str * 1e3;
    }
    return str;
  };
  const date = new Date(transformStr(time));
  const ymd = [
    digit(date.getFullYear(), 4),
    digit(date.getMonth() + 1),
    digit(date.getDate())
  ];
  const hms = [
    digit(date.getHours()),
    digit(date.getMinutes()),
    digit(date.getSeconds())
  ];
  return format
    .replace(/yyyy/g, ymd[0])
    .replace(/MM/g, ymd[1])
    .replace(/dd/g, ymd[2])
    .replace(/HH/g, hms[0])
    .replace(/mm/g, hms[1])
    .replace(/ss/g, hms[2])
    .replace(/YYYY/g, ymd[0])
    .replace(/DD/g, ymd[2]);
}
/*字符串转base64*/
export function encode(str) {
  // 对字符串进行编码
  let encode = encodeURI(str);
  // 对编码的字符串转化base64
  return btoa(encode);
}
/*base64转字符串*/
function decode(base64) {
  // 对base64转编码
  let decode = atob(base64);
  // 编码转字符串
  return decodeURI(decode);
}
