import { Timing } from '@antv/x6';

export default class Transition {
  execute(cellConfig, caseObj, result, isEditView) {
    /*if (result === true) {
      this.start(cellConfig, caseObj);
    } else {
      this.stop(cellConfig, caseObj);
    }*/
    this.start(cellConfig, caseObj, result, isEditView);
  }
  getNodeAnchorPoint(cell, anchor = 'center') {
    if (!cell?.isNode?.()) return null;
    const pos = cell.position?.();
    const size = cell.size?.();
    if (!pos || !size) return null;
    const { x, y } = pos;
    const { width, height } = size;
    switch (anchor) {
      case 'center':
      default:
        return { x: x + width / 2, y: y + height / 2 };
    }
  }
  start(cellConfig, caseObj, result, isEditView) {
    cellConfig.cell.stopTransition('position');
    let {
      max,
      duration,
      target,
      delay,
      timing = 'quad',
      mode = 'absolute',
      offset,
      bind
    } = caseObj.touchOff.transition.move;
    let { x: orgX, y: orgY } = cellConfig.orgCell.position;
    let targetX = target?.x;
    let targetY = target?.y;
    const dx = offset?.dx ?? 0;
    const dy = offset?.dy ?? 0;

    if (mode === 'relative') {
      targetX = orgX + dx;
      targetY = orgY + dy;
    } else if (mode === 'bind') {
      const graph = cellConfig.graph;
      const bindCellId = bind?.cellId;
      const anchor = bind?.anchor ?? 'center';
      let resolved = false;
      if (graph && bindCellId) {
        const bindCell = graph.getCellById?.(bindCellId);
        const p = this.getNodeAnchorPoint(bindCell, anchor);
        if (p) {
          targetX = p.x + dx;
          targetY = p.y + dy;
          resolved = true;
        }
      }
      // 预览/无 graph 时，使用配置里存的 target 作为快照锚点
      if (!resolved && targetX != null && targetY != null) {
        targetX = targetX + dx;
        targetY = targetY + dy;
      }
    }

    if (targetX == null || targetY == null) {
      targetX = orgX;
      targetY = orgY;
    }
    if (isEditView !== undefined) {
      result = max;
    }
    let movePer = result / max;
    movePer = movePer > 1 ? 1 : movePer;
    let x = (targetX - orgX) * movePer + orgX;
    let y = (targetY - orgY) * movePer + orgY;

    cellConfig.cell.transition(
      'position',
      { x, y },
      {
        delay: delay, //延时执行
        duration: duration,
        timing: Timing.decorators.reverse(Timing[timing]),
        finish: () => {
          if (isEditView !== undefined) {
            cellConfig.cell.position(orgX, orgY, {
              deep: true
            });
          }
        }
      }
    );
    cellConfig.cell.childrenTransition?.({
      x,
      y,
      delay,
      duration,
      timing,
      orgX,
      orgY,
      finish: (cell, orgX, orgY) => {
        if (isEditView !== undefined) {
          cell.position(orgX, orgY, {
            deep: true
          });
        }
      }
    });
  }
}
